        fig, ax = plt.subplots(figsize=(8, 4))
        cats = ['الفعلية', 'المثالي', 'الحد الأقصى']
        vals = [total_oil, oil_std['optimal'], oil_std['max']]
        colors = ['#43a047', '#1976d2', '#c62828']
