class SharedStorage:
    """تخزين مشترك بين الأجهزة عبر ملف JSON محلي."""
    _lock = threading.Lock()
    FILE = "tawor_shared_state.json"

    @classmethod
    def _load(cls):
        try:
            if os.path.exists(cls.FILE):
                with open(cls.FILE, "r", encoding="utf-8") as f:
                    return json.load(f)
        except Exception:
            pass
        return {}

    @classmethod
    def _save(cls, data):
        try:
            with cls._lock:
                tmp = cls.FILE + ".tmp"
                with open(tmp, "w", encoding="utf-8") as f:
                    json.dump(data, f, ensure_ascii=False, indent=2)
                os.replace(tmp, cls.FILE)
        except Exception:
            pass

    @classmethod
    def get(cls, key, default=None):
        with cls._lock:
            return cls._load().get(key, default)

    @classmethod
    def append_line(cls, key, line):
        with cls._lock:
            data = cls._load()
            current = data.get(key, "")
            data[key] = current + "\n" + line
            cls._save(data)
            return data[key]


try:
    _pc = SharedStorage.get("shared_comments")
    if _pc:
        st.session_state["shared_comments"] = _pc
except Exception:
    pass


def is_owner():
    return st.session_state.get("user_role") == "owner"


